"""Source-free contracts for opening scene comments, party states and associated items."""
from pathlib import Path
import unittest,json,hashlib,collections
R=Path(__file__).resolve().parents[1]
def load(p):return json.loads((R/p).read_bytes())
class OpeningCommentsTests(unittest.TestCase):
 def setUp(self):
  self.p=load('locales/zh-Hans/batch-110.json');self.r=load('locales/zh-Hans/batch-110.review.json');self.by={e['id']:e['translation'] for e in self.p['entries']};self.ts=list(self.by.values())
 def test_scope_and_classification(self):
  self.assertEqual(len(self.ts),227);self.assertEqual(self.r['status'],'draft');self.assertEqual(self.r['coverage'],[{'document': 'MC2Compose.int', 'section': 'PartyTalk_Juto', 'entries': 8}, {'document': 'MC2Compose.int', 'section': 'PartyTalk_Argo', 'entries': 10}, {'document': 'MC2Compose.int', 'section': 'PartyTalk_Zephi', 'entries': 10}, {'document': 'MC2Compose.int', 'section': 'PartyTalk_Crocell', 'entries': 7}, {'document': 'MC2Compose.int', 'section': 'PartyTalk_Celestin', 'entries': 3}, {'document': 'MC2Compose.int', 'section': 'Chapter00', 'entries': 28}, {'document': 'MC2Compose.int', 'section': 'Chapter01', 'entries': 28}, {'document': 'MC2Compose.int', 'section': 'Chapter02', 'entries': 55}, {'document': 'MC2Compose.int', 'section': 'Chapter03', 'entries': 71}, {'document': 'MC2Item.int', 'section': 'Valuables', 'entries': 7}])
  self.assertEqual(collections.Counter(e['text_kind'] for e in self.r['entries']),{'dialogue': 99, 'narrative': 81, 'tutorial': 22, 'menu_option': 10, 'quest_progress': 8, 'item_description': 6, 'item_name': 1});self.assertEqual(set(self.by),{e['id'] for e in self.r['entries']})
